import{_ as e,o as t,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-07-11","description":"","frontmatter":{"date":"2026-07-11T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-11-uxtrend.md","filePath":"daily/2026-07-11-uxtrend.md"}'),o={name:"daily/2026-07-11-uxtrend.md"};function s(i,r,g,p,h,d){return t(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-07-11" tabindex="-1">设计趋势 - 2026-07-11 <a class="header-anchor" href="#设计趋势-2026-07-11" aria-label="Permalink to &quot;设计趋势 - 2026-07-11&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域聚焦于AI在用户体验和设计工作流程中的应用。其中，代理UX设计原则的探索和Cursor IDE的自然对话式AI协作是值得关注的亮点。AI不仅改变了设计工作流程，提高了效率，还促使设计师创造更易于理解和信任的AI友好型产品。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探索设计新型数字设备用户体验的代理UX设计原则。</p><p><strong>能解决什么问题</strong>: 解决数字设备用户体验设计中人工智能代理的挑战。</p><p><strong>产品应用</strong>: 适用于产品设计，以人为中心，加速开发并强调人本原则。</p><p><strong>示例场景</strong>: 智能助手协助用户进行知识获取和团队协作。</p><hr><h3 id="_2-光标、氛围编码和手稿-ai所需的用户体验革命" tabindex="-1">2. 光标、氛围编码和手稿：AI所需的用户体验革命 <a class="header-anchor" href="#_2-光标、氛围编码和手稿-ai所需的用户体验革命" aria-label="Permalink to &quot;2. 光标、氛围编码和手稿：AI所需的用户体验革命&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/cursor-vibe-coding-and-manus-the-ux-revolution-that-ai-needs-3d3a0f8ccdfa" target="_blank" rel="noreferrer">Cursor, “vibe coding,” and Manus: the UX revolution that AI needs | by Amy Chivavibul | UX Collective</a></p><p><strong>一句话摘要</strong>: Cursor IDE通过自然对话与AI协作，提升开发效率。</p><p><strong>能解决什么问题</strong>: 提高开发者与AI协作的效率，减少操作复杂性。</p><p><strong>产品应用</strong>: 适用于软件开发，直接集成到开发环境中，提升代码编写和调试效率。</p><p><strong>示例场景</strong>: 开发者通过Cursor IDE直接与AI对话，优化代码性能。</p><hr><h3 id="_3-人工智能设计交互范式-类别、模式与设计考量" tabindex="-1">3. 人工智能设计交互范式：类别、模式与设计考量 <a class="header-anchor" href="#_3-人工智能设计交互范式-类别、模式与设计考量" aria-label="Permalink to &quot;3. 人工智能设计交互范式：类别、模式与设计考量&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://hanjing.medium.com/ai-interaction-paradigms-7caace4593ba" target="_blank" rel="noreferrer">AI Design Interaction Paradigms. Categories, Patterns, and Design… | by hanjing | Medium</a></p><p><strong>一句话摘要</strong>: AI通过多种交互范式重塑数字产品，提供可用、可信、直观的体验。</p><p><strong>能解决什么问题</strong>: 解决用户意图、自主性、可见性和控制的不同假设问题。</p><p><strong>产品应用</strong>: 适用于产品设计团队，指导创建AI体验。</p><p><strong>示例场景</strong>: 使用Agentic AI进行对话式交互设计。</p><hr><h3 id="_4-ai如何改变我的设计工作流程" tabindex="-1">4. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_4-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;4. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI让设计流程更快、更协作、更少猜测。</p><p><strong>能解决什么问题</strong>: 缩短从想法到原型的时间，提高设计效率。</p><p><strong>产品应用</strong>: 可以应用于产品设计，通过快速原型迭代加速产品开发。</p><p><strong>示例场景</strong>: 使用Figma和Cursor进行交互式原型设计。</p><hr><h3 id="_5-ai与设计-人工智能如何协助设计师以及设计师如何创造ai友好型产品" tabindex="-1">5. AI与设计：人工智能如何协助设计师以及设计师如何创造AI友好型产品 <a class="header-anchor" href="#_5-ai与设计-人工智能如何协助设计师以及设计师如何创造ai友好型产品" aria-label="Permalink to &quot;5. AI与设计：人工智能如何协助设计师以及设计师如何创造AI友好型产品&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@gwrx2005/ai-and-design-how-artificial-intelligence-assists-designers-and-how-designers-create-ai-friendly-df97320884ae" target="_blank" rel="noreferrer">AI and Design: How Artificial Intelligence Assists Designers and How Designers Create AI‑Friendly…</a></p><p><strong>一句话摘要</strong>: AI技术助力设计师工作流程，同时设计师需创造易于理解和信任的AI产品。</p><p><strong>能解决什么问题</strong>: 解决复杂AI系统用户界面设计和用户体验的直观性、信任度问题。</p><p><strong>产品应用</strong>: 可以应用于产品设计，通过AI工具增强设计流程，创造直观的AI驱动功能。</p><p><strong>示例场景</strong>: 设计一个聊天机器人，帮助用户通过自然语言与AI进行交互。</p><hr><h3 id="_6-ai代理工作流设计模式概览" tabindex="-1">6. AI代理工作流设计模式概览 <a class="header-anchor" href="#_6-ai代理工作流设计模式概览" aria-label="Permalink to &quot;6. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D | Binome | Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理、规划和执行任务。</p><p><strong>产品应用</strong>: 可应用于开发智能代理产品，通过工作流模式灵活处理问题。</p><p><strong>示例场景</strong>: 智能客服系统通过ReAct模式处理用户查询。</p><hr><h3 id="_7-为人工智能设计-设计人工智能特性的交互" tabindex="-1">7. 为人工智能设计：设计人工智能特性的交互 <a class="header-anchor" href="#_7-为人工智能设计-设计人工智能特性的交互" aria-label="Permalink to &quot;7. 为人工智能设计：设计人工智能特性的交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@ux.haowu/design-for-ai-2-designing-interactions-for-ai-features-d776d6388bdd" target="_blank" rel="noreferrer">Design for AI 2: Designing Interactions for AI Features</a></p><p><strong>一句话摘要</strong>: AI通过预测意图和实时补全，辅助用户保持专注。</p><p><strong>能解决什么问题</strong>: 解决用户在快节奏工作流程中快速输入和减少错误的问题。</p><p><strong>产品应用</strong>: 可应用于需要快速输入和减少输入错误的产品，如邮件客户端和编程应用。</p><p><strong>示例场景</strong>: 在Figma中自动补全地址，减少打字并降低错误。</p><hr><h3 id="_8-主动式ai工作流设计模式、示例及2025年展望" tabindex="-1">8. 主动式AI工作流设计模式、示例及2025年展望 <a class="header-anchor" href="#_8-主动式ai工作流设计模式、示例及2025年展望" aria-label="Permalink to &quot;8. 主动式AI工作流设计模式、示例及2025年展望&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/codex/agentic-ai-workflows-design-patterns-examples-and-what-to-watch-in-2025-a3602b19b7e8" target="_blank" rel="noreferrer">Agentic AI Workflows Design Patterns, Examples, and what to watch in 2025</a></p><p><strong>一句话摘要</strong>: 主动式AI工作流通过自动化系统管理并执行任务。</p><p><strong>能解决什么问题</strong>: 解决重复性工作，释放人力专注于高价值任务。</p><p><strong>产品应用</strong>: 适用于需要自动化、智能化处理复杂任务的场景。</p><p><strong>示例场景</strong>: 智能物流系统自动规划货物配送路线。</p><hr><h3 id="_9-ai时代下的用户体验2-0-代理体验设计" tabindex="-1">9. AI时代下的用户体验2.0：代理体验设计 <a class="header-anchor" href="#_9-ai时代下的用户体验2-0-代理体验设计" aria-label="Permalink to &quot;9. AI时代下的用户体验2.0：代理体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">UX 2.0 (Agent Experience): Experience Design in the Age of AI Agents</a></p><p><strong>一句话摘要</strong>: AI代理改变了用户体验设计，从人机交互转向代理与系统的交互。</p><p><strong>能解决什么问题</strong>: 如何为非人类用户——AI代理——设计直观、满足需求的体验。</p><p><strong>产品应用</strong>: 可以应用到任何需要AI代理自动化处理任务的产品中，如智能助手、自动化客服。</p><p><strong>示例场景</strong>: AI代理自动为用户预约医生，无需用户手动操作。</p><hr><h3 id="_10-引入代理体验-ax" tabindex="-1">10. 引入代理体验（AX） <a class="header-anchor" href="#_10-引入代理体验-ax" aria-label="Permalink to &quot;10. 引入代理体验（AX）&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://valentinaalto.medium.com/introducing-agent-experience-ax-29aff68cd30f" target="_blank" rel="noreferrer">Introducing Agent Experience (AX) | by Valentina Alto | Jun, 2026 | Medium</a></p><p><strong>一句话摘要</strong>: 代理体验（AX）关注于人与智能代理之间的长期合作关系。</p><p><strong>能解决什么问题</strong>: 解决软件从应用转变为智能合作伙伴时的交互和信任问题。</p><p><strong>产品应用</strong>: 可以应用于需要智能代理参与工作流程的实际产品中，如自动化客户服务。</p><p><strong>示例场景</strong>: 智能助手在客户服务中持续参与并维护对话上下文。</p><hr>',75)])])}const A=e(o,[["render",s]]);export{c as __pageData,A as default};
